def suggest(prefix):
    # runs on every keystroke, over the full search log
    return db.query(
      "SELECT q FROM search_log WHERE q LIKE %s "
      "GROUP BY q ORDER BY count(*) DESC LIMIT 10",
      prefix + '%')

